import json,base64,html,re,io
from pathlib import Path
from PIL import Image

ROOT=Path('docs/asset-comparison')
inventory=json.loads((ROOT/'inventory.json').read_text())
choices=json.loads((ROOT/'alternatives.json').read_text())
labels={'scout':'T-600 Scout','endo':'T-800 Endoskeleton','heavy':'T-800 Heavy','t1000':'T-1000','hkaerial':'HK-Aerial','hktank':'HK-Tank','soldier':'Resistance Soldier','wall':'Wall segment','floor':'Floor slab','stair':'Stair tread','rubble':'Rubble bank','truck':'Wrecked truck','barrel':'Barrel','bunker':'Bunker shell module','container':'Shipping container','ramp':'Loading ramp','tunnel':'Tunnel wall','column':'Support column','supply':'Supply chests','sandbags':'Sandbag cover','generator':'Power generator','spool':'Cable spool','bunk':'Field bed','trader':'Trader station','door':'Bunker door','gate':'Spawn gate','hazard':'Hazard grate','flank':'Breakable flank wall','tube':'Tube light','emergency':'Emergency light','work':'Work light','pipe':'Service pipe','cable':'Electrical cable'}
architecture={'wall','floor','stair','bunker','ramp','tunnel','column','door','gate','flank'}
def family(id):
    if id.startswith('unit-'):return id[5:]
    name=id[4:]
    if name.startswith('light-fixture-'):return name[14:]
    return name.split('-')[0]
def category(row):
    f=family(row['id'])
    if row['id'].startswith('unit-'):return 'Units'
    if f in architecture:return 'Architecture'
    if f in {'tube','emergency','work','pipe','cable','hazard'}:return 'Fixtures'
    return 'Props'
order={'Units':0,'Props':1,'Fixtures':2,'Architecture':3}
inventory.sort(key=lambda r:order[category(r)])
E=lambda x:html.escape(str(x),quote=True)
assets={}
def img(path):
    if path not in assets:
        with Image.open(ROOT/path) as im:
            im=im.convert('RGB');im.thumbnail((720,450));b=io.BytesIO();im.save(b,format='JPEG',quality=85);assets[path]='data:image/jpeg;base64,'+base64.b64encode(b.getvalue()).decode()
    return path
def preview(path,name):
    return f'<button class="preview" data-preview="{E(img(path))}" aria-label="Enlarge {E(name)}"><img data-image="{E(path)}" alt="{E(name)}" width="640" height="400" loading="lazy"><span>Enlarge ↗</span></button>'
def badge(text,cls=''):
    return f'<span class="badge {cls}">{E(text)}</span>'
sections=[]
for i,r in enumerate(inventory):
    f=family(r['id']);assert f in choices,r['id']
    title=labels[f]
    if f=='container':title+=' · '+r['id'].split('-')[-1].title()
    variant=re.search(r'(\d+(?:p\d+)?x\d+(?:p\d+)?(?:x\d+(?:p\d+)?)?)',r['id'])
    if variant:title+=' · '+variant[1].replace('p','.').replace('x',' × ')
    count=len(r['names']);size=' × '.join(f'{x:.2f}'.rstrip('0').rstrip('.') for x in r['render']['size'])
    original=f'<th scope="row" class="original">{preview(r["image"],title)}<div class="cellbody"><div class="eyebrow">{i+1:02d} / {category(r)}</div><h2>{E(title)}</h2><div class="badges">{badge(str(count)+(" placement" if count==1 else " placements"))}{badge(format(r["render"]["triangles"],",")+" tris")}</div><p class="muted">Current project model · neutral studio render</p><details><summary>Scene references &amp; original file</summary><p class="path">{E(r["id"])}</p><p>Model bounds: {size} scene units.</p><p>{E(", ".join(r["names"]))}</p><a href="../../{E(r["path"])}">Original glTF ↗</a></details></div></th>'
    cells=[]
    for a in choices[f]:
        license=a['license'].replace('CC Attribution','CC BY').replace('-NonCommercial','-NC').replace('-ShareAlike','-SA').replace('-NoDerivs','-ND')
        tri='PBR texture set' if a['triangles'] is None else f'{a["triangles"]:,} tris'
        note=''
        if a['triangles'] and a['triangles']>100000:note='<p class="caution">High mesh cost · plan LODs / simplification.</p>'
        elif a['triangles'] and a['triangles']>40000:note='<p class="caution">Review mesh cost for repeated placements.</p>'
        if 'NonCommercial' in a['license']:note+='<p class="caution">Listed for noncommercial use.</p>'
        anim=f' · {a["animations"]} listed animation'+('s' if a['animations']!=1 else '') if a['animations'] else ''
        cells.append(f'<td>{preview(a["image"],a["name"])}<div class="cellbody"><div class="eyebrow">{E(a["source"])} · downloadable</div><h3><a href="{E(a["url"])}" target="_blank" rel="noopener noreferrer">{E(a["name"])} ↗</a></h3><p class="credit">by {E(a["author"])}</p><div class="badges">{badge(license,"license")}{badge(tri)}</div><p>{E(a["why"])}</p><p class="fit">{E(a["fit"])}</p>{note}<p class="metadata">Uploader-listed license{E(anim)}.</p></div></td>')
    search=' '.join([title,r['id'],category(r),*r['names'],*[a['name'] for a in choices[f]]]).lower()
    sections.append(f'<tr data-category="{category(r)}" data-search="{E(search)}" id="{E(r["id"])}">{original}{"".join(cells)}</tr>')
counts={c:sum(category(r)==c for r in inventory) for c in order}
unique=len({a['id'] for v in choices.values() for a in v})
tabs='<button class="filter active" data-filter="All" aria-pressed="true">All assets <b>76</b></button>'+''.join(f'<button class="filter" data-filter="{c}" aria-pressed="false">{c} <b>{n}</b></button>' for c,n in counts.items())
style='''
:root{color-scheme:dark;--bg:#0c1014;--panel:#11171d;--line:#2a343e;--muted:#a0afbc;--ink:#edf3f7;--accent:#a9d7f4}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.5 system-ui,-apple-system,sans-serif}button,input{font:inherit}a{color:var(--accent);text-decoration:none}a:hover{text-decoration:underline}button{cursor:pointer}header,main,footer{max-width:1760px;margin:auto;padding:26px 32px}header{padding-bottom:18px}.topline{display:flex;justify-content:space-between;gap:20px;align-items:center}.kicker,.eyebrow{text-transform:uppercase;letter-spacing:.12em;font-size:12px;font-weight:650;color:var(--muted)}.kicker{color:#ee856e}h1{font-size:clamp(26px,3vw,38px);letter-spacing:-.04em;line-height:1.15;margin:9px 0 12px}header p{max-width:1040px;color:var(--muted);margin:8px 0}.numbers{display:flex;gap:26px}.numbers strong{display:block;font-size:25px;font-weight:550;color:var(--ink)}.numbers span{font-size:12px;color:var(--muted);white-space:nowrap}main{padding-top:0}.tools{display:flex;justify-content:space-between;gap:18px;flex-wrap:wrap;align-items:center;padding:17px 0 21px}.filters{display:flex;gap:7px;flex-wrap:wrap}.filter{color:var(--muted);background:transparent;border:1px solid var(--line);border-radius:5px;padding:8px 12px;font-size:14px}.filter b{font-size:12px;margin-left:6px;opacity:.7}.filter.active{background:#e5eef5;color:#18232d;border-color:#e5eef5}.searchbox{display:flex;align-items:center;gap:10px;font-size:14px;color:var(--muted)}input{border:1px solid var(--line);border-radius:5px;background:var(--panel);color:var(--ink);padding:9px 12px;width:280px;font-size:14px}.tablewrap{overflow:auto;border:1px solid var(--line);border-radius:6px;max-height:calc(100vh - 90px)}table{border-collapse:separate;border-spacing:0;width:100%;table-layout:fixed;min-width:1050px}thead th{position:sticky;top:0;z-index:3;background:#202b35;text-align:left;padding:15px 17px;font-size:14px;border-bottom:1px solid #4a5a67;font-weight:600}thead th:first-child{background:#2c3d4c}thead small{display:block;font-weight:400;font-size:12px;color:#bac7d2;margin-top:3px}td,tbody th{padding:0;vertical-align:top;border-right:1px solid var(--line);border-bottom:1px solid var(--line);background:var(--panel);text-align:left;font-weight:400}td:last-child{border-right:0}.original{background:#17212a}.cellbody{padding:17px 17px 22px}h2,h3{font-size:17px;line-height:1.35;letter-spacing:-.01em;margin:7px 0 10px;font-weight:620}h3 a{color:var(--ink)}p{margin:10px 0}.cellbody p{font-size:14px}.preview{border:0;padding:0;display:block;width:100%;position:relative;background:#151c23;aspect-ratio:1.6;overflow:hidden}.preview img{width:100%;height:100%;object-fit:contain;display:block}.preview span{position:absolute;right:9px;bottom:9px;border-radius:3px;background:#0a111bd9;color:white;padding:3px 7px;font-size:12px;opacity:0}.preview:hover span,.preview:focus-visible span{opacity:1}.badges{display:flex;gap:5px;flex-wrap:wrap;margin:12px 0}.badge{font-size:12px;color:#bdcbd6;border:1px solid #394754;border-radius:4px;padding:3px 6px}.badge.license{color:#afd6bf;border-color:#345d4a}.muted,.credit,.metadata{color:var(--muted)}.credit{margin:0;font-size:12px!important}.fit{color:#b8d6e8;border-left:2px solid #49758b;padding-left:9px}.caution{color:#e5b984;font-size:12px!important}.metadata{font-size:12px!important}details{font-size:13px;color:var(--muted);margin-top:16px}summary{cursor:pointer;color:#c5d6e2}.path{overflow-wrap:anywhere;font-family:ui-monospace,monospace;font-size:12px!important}details p{font-size:12px!important;overflow-wrap:anywhere}.resultcount{font-size:12px;color:var(--muted);margin:0 0 8px}#empty{padding:30px;text-align:center;color:var(--muted)}footer{padding-top:4px;padding-bottom:35px;font-size:13px;color:var(--muted)}footer p{max-width:1150px}footer summary{font-size:14px}dialog{border:1px solid #526779;border-radius:9px;background:#10171f;color:white;padding:14px;max-width:94vw;max-height:94vh;width:960px}dialog::backdrop{background:#000c}dialog img{width:100%;max-height:72vh;object-fit:contain;background:#151c23}dialog .dialogtop{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:12px}dialog button{background:#293846;color:white;border:1px solid #597084;border-radius:4px;padding:5px 12px}button:focus-visible,a:focus-visible,input:focus-visible,summary:focus-visible{outline:2px solid #c1e6ff;outline-offset:3px}[hidden]{display:none!important}@media(max-width:850px){header,main,footer{padding-left:16px;padding-right:16px}.numbers{gap:15px}.topline{align-items:flex-start;flex-wrap:wrap}.numbers strong{font-size:20px}.numbers span{font-size:11px}.tools{gap:12px}.searchbox{width:100%;justify-content:space-between}input{width:70%}.tablewrap{max-height:78vh}header p{font-size:14px}}@media print{.tools,.numbers,.preview span{display:none}body{background:white;color:black}.tablewrap{overflow:visible;max-height:none}table{min-width:0}td,th,.original{background:white!important;color:black!important}h3 a{color:black}header,main,footer{padding:10px}.cellbody{padding:8px}tr{break-inside:avoid}.preview{aspect-ratio:1.8}thead th{position:static}}
'''
script='''
const images=IMAGES;
document.querySelectorAll('[data-image]').forEach(el=>el.src=images[el.dataset.image]);
const rows=[...document.querySelectorAll('tbody tr')],search=document.querySelector('#search');let active='All';
function filter(){let count=0;const q=search.value.trim().toLowerCase();for(const r of rows){const show=(active==='All'||r.dataset.category===active)&&r.dataset.search.includes(q);r.hidden=!show;if(show)count++}document.querySelector('#resultcount').textContent=`${count} of 76 assets shown`;document.querySelector('#empty').hidden=count>0;}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{active=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{const on=x===b;x.classList.toggle('active',on);x.setAttribute('aria-pressed',on)});filter()}));search.addEventListener('input',filter);
const dialog=document.querySelector('dialog');let trigger;
document.querySelectorAll('[data-preview]').forEach(b=>b.addEventListener('click',()=>{trigger=b;dialog.querySelector('img').src=images[b.dataset.preview];dialog.querySelector('img').alt=b.querySelector('img').alt;dialog.querySelector('#dialog-title').textContent=b.querySelector('img').alt;dialog.showModal()}));dialog.querySelector('button').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog.addEventListener('close',()=>trigger?.focus());
'''.replace('IMAGES',json.dumps(assets,separators=(',',':')))
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Terminator — scene asset alternatives</title><meta name="description" content="76 original scene models compared with three downloadable asset alternatives each."><style>{style}</style></head><body>
<header><div class="topline"><div><div class="kicker">Terminator / Bunker 7</div><h1>Scene asset alternatives</h1></div><div class="numbers"><div><strong>76</strong><span>original assets</span></div><div><strong>{unique}</strong><span>distinct alternatives</span></div><div><strong>273</strong><span>scene placements</span></div></div></div><p>One row per unique model in the saved scene. Compare the original with three alternatives; click a preview to enlarge it or an asset title to open its source.</p><p style="font-size:13px">Size variants remain separate rows and share suitable alternatives. Floor options upgrade the material on the existing slab. Sources checked September 12, 2026.</p></header>
<main><div class="tools"><nav class="filters" aria-label="Asset categories">{tabs}</nav><label class="searchbox" for="search">Find an asset<input id="search" type="search" placeholder="Name, scene object, or model…"></label></div><p class="resultcount" id="resultcount" aria-live="polite">76 of 76 assets shown</p><div class="tablewrap" tabindex="0" role="region" aria-label="Asset comparison; scroll horizontally on small screens"><table><caption style="position:absolute;clip-path:inset(50%);width:1px;height:1px;overflow:hidden">Each row compares one original asset with three alternatives found online.</caption><thead><tr><th scope="col">Original asset<small>Rendered from your project</small></th><th scope="col">Alternative 01<small>Source preview + fit notes</small></th><th scope="col">Alternative 02<small>Source preview + fit notes</small></th><th scope="col">Alternative 03<small>Source preview + fit notes</small></th></tr></thead><tbody>{''.join(sections)}</tbody></table><p id="empty" hidden>No matching assets. Try a broader name or another category.</p></div></main>
<footer><details><summary>Coverage, sources &amp; integration notes</summary><p>Inventory: <code>assets/main.scene.gltf</code>, resolved through <code>assets.json</code>. All 76 referenced models and their 273 placements are represented. Cameras, lights, organizational groups, the manager and player-start marker are scene controls rather than replacement models. Unused imports and runtime-only effects or weapons are outside this saved-model inventory.</p><p>Original images are renders of the actual local glTF geometry and materials under common studio lighting. They show each asset at its native scale before scene-instance transforms. Alternatives use the creators’ listing thumbnails; lighting and apparent scale are not matched.</p><p>Sources: <a href="https://sketchfab.com" target="_blank" rel="noopener noreferrer">Sketchfab</a> model listings and <a href="https://polyhaven.com" target="_blank" rel="noopener noreferrer">Poly Haven</a> texture listings, with a direct source link on every alternative. Download availability, animation counts and licenses are provider-listed; an account may be needed. Character rigs and Kite3D compatibility have not been tested. Fan models and recognizable franchise content require separate provenance and rights review.</p><p>Fit notes are editorial recommendations. Replacement models need scale, pivot, collider and material checks. Moving gates, destructible walls, unit joints and gameplay effects need to be connected to the existing behavior. Whole-building candidates are redesign references that require extracting or rebuilding modules. No scene models were replaced.</p></details></footer>
<dialog aria-labelledby="dialog-title"><div class="dialogtop"><strong id="dialog-title"></strong><button type="button" autofocus>Close ✕</button></div><img alt=""></dialog><script>{script}</script></body></html>'''
(ROOT/'index.html').write_text(page)
print(f'Built {len(inventory)} rows, {len(inventory)*3} alternative cells, {unique} unique candidates; {len(page)/1e6:.1f} MB self-contained HTML.')
